import fs from 'node:fs';
import crypto from 'node:crypto';

const read=p=>fs.readFileSync(p,'utf8');
const write=(p,s)=>fs.writeFileSync(p,s);
function rep(s,a,b,label=a.slice(0,80)){if(!s.includes(a))throw new Error('Missing baseline for '+label);return s.replace(a,b)}
function blobSha(path){const b=fs.readFileSync(path);return crypto.createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${b.length}\0`),b])).digest('hex')}

// ----- Core v1.1 -----
let core=read('rah-command-center-core.js');
core=rep(core,"const CC_VERSION='1.0.0',RAVEN_VERSION='2.0.32',BRIDGE_BASE='http://127.0.0.1:18765',DEVICE_STORAGE_KEY='rah.cc.devices.v1',NODE_AGENT_PORT=18766,NODE_AGENT_PROTOCOL='rah-node-health-v1',NODE_STORAGE_PROTOCOL='rah-node-storage-v1',NODE_ACTIONS_PROTOCOL='rah-node-actions-v1',NODE_LAUNCH_PROTOCOL='rah-node-launch-v1',NODE_HANDOFF_PROTOCOL='rah-node-handoff-v1';","const CC_VERSION='1.1.0',RAVEN_VERSION='2.0.32',BRIDGE_BASE='http://127.0.0.1:18765',DEVICE_STORAGE_KEY='rah.cc.devices.v1',NODE_AGENT_PORT=18766,NODE_AGENT_PROTOCOL='rah-node-health-v1',NODE_STORAGE_PROTOCOL='rah-node-storage-v1',NODE_ACTIONS_PROTOCOL='rah-node-actions-v2',NODE_LAUNCH_PROTOCOL='rah-node-launch-v1',NODE_HANDOFF_PROTOCOL='rah-node-handoff-v1',ACTION_CHALLENGE_HEADER='X-RAH-Action-Challenge',ACTION_CHALLENGE_TTL_SECONDS=60;",'core constants');
const oldCatalog=`function sanitizeActionCatalog(p,capabilities){if(!isPlainObject(p)||p.protocol!==NODE_ACTIONS_PROTOCOL||p.status!=='ready'||!Array.isArray(p.actions))return null;const caps=sanitizeCapabilities(capabilities),out=[];for(const raw of p.actions){if(!isPlainObject(raw))continue;const id=cleanText(raw.id,'',48),catalog=ACTION_CATALOG[id];if(!catalog||!caps.includes(catalog.capability))continue;if(raw.method!==catalog.method||raw.path!==catalog.path||raw.capability!==catalog.capability||raw.scope!==catalog.scope||raw.mutating!==catalog.mutating)continue;if(catalog.input&&raw.input!==catalog.input)continue;if(!catalog.input&&raw.input!==undefined)continue;if(!out.includes(id))out.push(id)}return{protocol:NODE_ACTIONS_PROTOCOL,status:'ready',actions:out}}`;
const newCatalog=`function sanitizeActionChallenge(v){if(typeof v!=='string'||v!==v.trim())return'';return /^[A-Za-z0-9_-]{24,64}$/.test(v)?v:''}\nfunction validateActionRow(raw,caps){if(!isPlainObject(raw))return null;const id=cleanText(raw.id,'',48),catalog=ACTION_CATALOG[id];if(!catalog||!caps.includes(catalog.capability))return null;if(raw.method!==catalog.method||raw.path!==catalog.path||raw.capability!==catalog.capability||raw.scope!==catalog.scope||raw.mutating!==catalog.mutating)return null;if(catalog.input&&raw.input!==catalog.input)return null;if(!catalog.input&&raw.input!==undefined)return null;const challenge=sanitizeActionChallenge(raw.challenge);if(!challenge||raw.challengeTtlSeconds!==ACTION_CHALLENGE_TTL_SECONDS)return null;return{id,catalog,challenge}}\nfunction sanitizeActionCatalog(p,capabilities){if(!isPlainObject(p)||p.protocol!==NODE_ACTIONS_PROTOCOL||p.status!=='ready'||!Array.isArray(p.actions))return null;const caps=sanitizeCapabilities(capabilities),out=[];for(const raw of p.actions){const row=validateActionRow(raw,caps);if(row&&!out.includes(row.id))out.push(row.id)}return{protocol:NODE_ACTIONS_PROTOCOL,status:'ready',actions:out}}\nfunction actionChallengeFromCatalog(p,capabilities,actionId){if(!isPlainObject(p)||p.protocol!==NODE_ACTIONS_PROTOCOL||p.status!=='ready'||!Array.isArray(p.actions))return'';const caps=sanitizeCapabilities(capabilities),wanted=cleanText(actionId,'',48);for(const raw of p.actions){const row=validateActionRow(raw,caps);if(row&&row.id===wanted)return row.challenge}return''}`;
core=rep(core,oldCatalog,newCatalog,'core action catalog sanitizer');
const oldRequests=`function actionExecutionRequest(record,actionId){if(actionId==='rustdesk.connect'||!canExecuteAction(record,actionId))return null;const a=ACTION_CATALOG[actionId],url=actionExecutionUrl(record,actionId);return url?{id:a.id,url,method:a.method,mutating:a.mutating,scope:a.scope}:null}\nfunction rustDeskHandoffRequest(record,peerId){if(!canExecuteAction(record,'rustdesk.connect'))return null;const id=sanitizePeerId(peerId),url=nodeRustDeskHandoffUrl(record.endpointIp);return id&&url?{id:'rustdesk.connect',url,method:'POST',body:{peerId:id}}:null}`;
const newRequests=`function actionChallengeRequest(record,actionId){if(!canExecuteAction(record,actionId))return null;const url=nodeActionsUrl(record.endpointIp);return url?{id:actionId,url,method:'GET'}:null}\nfunction actionExecutionRequest(record,actionId,challenge){if(actionId==='rustdesk.connect'||!canExecuteAction(record,actionId))return null;const c=sanitizeActionChallenge(challenge),a=ACTION_CATALOG[actionId],url=actionExecutionUrl(record,actionId);return c&&url?{id:a.id,url,method:a.method,mutating:a.mutating,scope:a.scope,challenge:c}:null}\nfunction rustDeskHandoffRequest(record,peerId,challenge){if(!canExecuteAction(record,'rustdesk.connect'))return null;const id=sanitizePeerId(peerId),c=sanitizeActionChallenge(challenge),url=nodeRustDeskHandoffUrl(record.endpointIp);return id&&c&&url?{id:'rustdesk.connect',url,method:'POST',challenge:c,body:{peerId:id}}:null}`;
core=rep(core,oldRequests,newRequests,'core request builders');
core=rep(core,'NODE_LAUNCH_PROTOCOL,NODE_HANDOFF_PROTOCOL,CAPABILITY_IDS','NODE_LAUNCH_PROTOCOL,NODE_HANDOFF_PROTOCOL,ACTION_CHALLENGE_HEADER,ACTION_CHALLENGE_TTL_SECONDS,CAPABILITY_IDS','core exports constants');
core=rep(core,'sanitizeActionIds,sanitizeActionCatalog,sanitizeStorageSummary','sanitizeActionIds,sanitizeActionChallenge,sanitizeActionCatalog,actionChallengeFromCatalog,sanitizeStorageSummary','core exports challenge sanitizer');
core=rep(core,'canExecuteAction,actionExecutionUrl,actionExecutionRequest,rustDeskHandoffRequest','canExecuteAction,actionChallengeRequest,actionExecutionUrl,actionExecutionRequest,rustDeskHandoffRequest','core exports challenge request');
write('rah-command-center-core.js',core);

// ----- Node Agent v0.7 -----
let agent=read('rah-node-agent.py');
agent=rep(agent,'import argparse,hmac,json,os,platform,re,secrets,shutil,socket,subprocess','import argparse,hmac,json,os,platform,re,secrets,shutil,socket,subprocess,threading,time','agent imports');
agent=rep(agent,'AGENT_VERSION="0.6.0";PROTOCOL="rah-node-health-v1";STORAGE_PROTOCOL="rah-node-storage-v1";ACTIONS_PROTOCOL="rah-node-actions-v1";LAUNCH_PROTOCOL="rah-node-launch-v1";HANDOFF_PROTOCOL="rah-node-handoff-v1";PORT=18766','AGENT_VERSION="0.7.0";PROTOCOL="rah-node-health-v1";STORAGE_PROTOCOL="rah-node-storage-v1";ACTIONS_PROTOCOL="rah-node-actions-v2";LAUNCH_PROTOCOL="rah-node-launch-v1";HANDOFF_PROTOCOL="rah-node-handoff-v1";ACTION_CHALLENGE_HEADER="X-RAH-Action-Challenge";ACTION_CHALLENGE_TTL_SECONDS=60;PORT=18766','agent constants');
const agentBuild=`def build_actions_payload(capabilities=None,app_paths=None):\n caps=sanitize_capabilities(capabilities);paths=build_app_paths(app_paths);actions=[]\n for action_id in ("storage-summary.read","rustdesk.launch","rustdesk.connect"):\n  action=ACTION_CATALOG[action_id]\n  if action["capability"] not in caps:continue\n  if action_id.startswith("rustdesk.") and not paths.get("rustdesk"):continue\n  actions.append(dict(action))\n return {"protocol":ACTIONS_PROTOCOL,"status":"ready","actions":actions,"approvalMode":"command-center-local"}`;
const agentBuildNew=`def build_actions_payload(capabilities=None,app_paths=None):\n caps=sanitize_capabilities(capabilities);paths=build_app_paths(app_paths);actions=[]\n for action_id in ("storage-summary.read","rustdesk.launch","rustdesk.connect"):\n  action=ACTION_CATALOG[action_id]\n  if action["capability"] not in caps:continue\n  if action_id.startswith("rustdesk.") and not paths.get("rustdesk"):continue\n  actions.append(dict(action))\n return {"protocol":ACTIONS_PROTOCOL,"status":"ready","actions":actions,"approvalMode":"command-center-local"}\ndef issue_action_challenges(base_payload,state,lock,ttl_seconds=ACTION_CHALLENGE_TTL_SECONDS,now=None):\n ttl=max(1,int(ttl_seconds));ts=time.monotonic() if now is None else float(now);actions=[]\n with lock:\n  state.clear()\n  for action in base_payload.get("actions",[]):\n   challenge=secrets.token_urlsafe(24);state[action["id"]]={"value":challenge,"expires":ts+ttl};item=dict(action);item["challenge"]=challenge;item["challengeTtlSeconds"]=ttl;actions.append(item)\n return {"protocol":ACTIONS_PROTOCOL,"status":"ready","actions":actions,"approvalMode":"command-center-local"}\ndef consume_action_challenge(state,lock,action_id,value,now=None):\n if not isinstance(value,str) or not value:return "missing"\n ts=time.monotonic() if now is None else float(now)\n with lock:\n  entry=state.get(action_id)\n  if not entry:return "invalid"\n  if ts>entry["expires"]:state.pop(action_id,None);return "invalid"\n  if not hmac.compare_digest(value,entry["value"]):return "invalid"\n  state.pop(action_id,None);return "ok"`;
agent=rep(agent,agentBuild,agentBuildNew,'agent challenge helpers');
agent=rep(agent,'def make_handler(token,node_name="",node_role="",capabilities=None,app_paths=None,app_launcher=None,handoff_launcher=None):\n caps=sanitize_capabilities(capabilities);paths=build_app_paths(app_paths);health_payload=build_health_payload(node_name,node_role,caps);actions_payload=build_actions_payload(caps,paths);launcher=app_launcher or launch_executable;handoff=handoff_launcher or launch_rustdesk_connect','def make_handler(token,node_name="",node_role="",capabilities=None,app_paths=None,app_launcher=None,handoff_launcher=None,challenge_ttl_seconds=ACTION_CHALLENGE_TTL_SECONDS):\n caps=sanitize_capabilities(capabilities);paths=build_app_paths(app_paths);health_payload=build_health_payload(node_name,node_role,caps);actions_payload=build_actions_payload(caps,paths);challenge_state={};challenge_lock=threading.Lock();launcher=app_launcher or launch_executable;handoff=handoff_launcher or launch_rustdesk_connect','agent handler signature');
agent=rep(agent,'self.send_header("Access-Control-Allow-Headers","Authorization, Content-Type")','self.send_header("Access-Control-Allow-Headers","Authorization, Content-Type, "+ACTION_CHALLENGE_HEADER)','agent CORS challenge header');
agent=rep(agent,'  def _handoff_peer_id(self):','  def _fresh_actions_payload(self):return issue_action_challenges(actions_payload,challenge_state,challenge_lock,challenge_ttl_seconds)\n  def _require_action_challenge(self,action_id):\n   result=consume_action_challenge(challenge_state,challenge_lock,action_id,self.headers.get(ACTION_CHALLENGE_HEADER,""))\n   if result=="ok":return True\n   self._json(428 if result=="missing" else 409,{"error":"action_challenge_required" if result=="missing" else "action_challenge_invalid_or_expired"});return False\n  def _handoff_peer_id(self):','agent handler challenge methods');
agent=rep(agent,'   if self.path=="/actions":self._json(200,actions_payload);return\n   payload=build_storage_payload(caps)\n   if payload is None:self._json(403,{"error":"storage_capability_not_enabled"});return\n   self._json(200,payload)','   if self.path=="/actions":self._json(200,self._fresh_actions_payload());return\n   payload=build_storage_payload(caps)\n   if payload is None:self._json(403,{"error":"storage_capability_not_enabled"});return\n   if not self._require_action_challenge("storage-summary.read"):return\n   self._json(200,payload)','agent GET challenge');
agent=rep(agent,'   if self.path=="/launch/rustdesk":\n    if self.headers.get("Transfer-Encoding") or int(self.headers.get("Content-Length","0") or 0)!=0:self._json(400,{"error":"request_body_not_allowed"});return\n    try:ok=bool(launcher(path))','   if self.path=="/launch/rustdesk":\n    if self.headers.get("Transfer-Encoding") or int(self.headers.get("Content-Length","0") or 0)!=0:self._json(400,{"error":"request_body_not_allowed"});return\n    if not self._require_action_challenge("rustdesk.launch"):return\n    try:ok=bool(launcher(path))','agent launch challenge');
agent=rep(agent,'   peer_id=self._handoff_peer_id()\n   if peer_id is None:return\n   try:ok=bool(handoff(path,peer_id))','   peer_id=self._handoff_peer_id()\n   if peer_id is None:return\n   if not self._require_action_challenge("rustdesk.connect"):return\n   try:ok=bool(handoff(path,peer_id))','agent handoff challenge');
agent=rep(agent,'def create_server(host,port,token,node_name="",node_role="",capabilities=None,app_paths=None,app_launcher=None,handoff_launcher=None):return ThreadingHTTPServer((host,port),make_handler(token,node_name,node_role,capabilities,app_paths,app_launcher,handoff_launcher))','def create_server(host,port,token,node_name="",node_role="",capabilities=None,app_paths=None,app_launcher=None,handoff_launcher=None,challenge_ttl_seconds=ACTION_CHALLENGE_TTL_SECONDS):return ThreadingHTTPServer((host,port),make_handler(token,node_name,node_role,capabilities,app_paths,app_launcher,handoff_launcher,challenge_ttl_seconds))','agent server signature');
agent=rep(agent,'p=argparse.ArgumentParser(description="RAH Node Agent — explicit identity, fixed action catalog, read-only storage, fixed app launch and password-free RustDesk handoff")','p=argparse.ArgumentParser(description="RAH Node Agent — explicit identity, fixed action catalog, one-time action challenges, read-only storage, fixed app launch and password-free RustDesk handoff")','agent description');
agent=rep(agent,'print("GET /health and GET /actions are authenticated. GET /storage remains fixed-volume and read-only.");print("POST /launch/rustdesk accepts no body, path or arguments and launches only the fixed RustDesk executable.");print("POST /handoff/rustdesk accepts only one validated peerId and internally uses the fixed --connect form; passwords are never accepted.")','print("GET /health and GET /actions are authenticated. Each explicit /actions read issues fresh 60-second single-use action challenges in memory only.");print("GET /storage requires the storage-summary.read challenge and remains fixed-volume/read-only.");print("POST /launch/rustdesk requires the rustdesk.launch challenge, accepts no body/path/arguments and launches only the fixed RustDesk executable.");print("POST /handoff/rustdesk requires the rustdesk.connect challenge, accepts only one validated peerId and internally uses the fixed --connect form; passwords are never accepted.")','agent console');
