html=rep(html,"async function authRequest(url,token,method,body){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),5000),headers={Authorization:'Bearer '+token},opts={method,headers,credentials:'omit',cache:'no-store',signal:ctl.signal};if(body!==undefined){headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}try{const r=await fetch(url,opts);let payload=null;try{payload=await r.json()}catch(_){}return{ok:r.ok,status:r.status,payload}}finally{clearTimeout(timer)}}","async function authRequest(url,token,method,body,challenge){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),5000),headers={Authorization:'Bearer '+token},opts={method,headers,credentials:'omit',cache:'no-store',signal:ctl.signal};if(challenge)headers[core.ACTION_CHALLENGE_HEADER]=challenge;if(body!==undefined){headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}try{const r=await fetch(url,opts);let payload=null;try{payload=await r.json()}catch(_){}return{ok:r.ok,status:r.status,payload}}finally{clearTimeout(timer)}}",'html authRequest');
const oldRun=`async function runApprovedAction(){const id=document.getElementById('actionDevice').value,action=document.getElementById('actionId').value,token=document.getElementById('actionToken').value.trim(),out=document.getElementById('actionResult'),d=devices.find(x=>x.id===id),req=d?core.actionExecutionRequest(d,action):null;if(!req||!token){out.className='result bad';out.textContent='Action is not both advertised and locally approved, or token is missing.';return}out.className='result';out.textContent='Running approved fixed action…';try{const res=await authRequest(req.url,token,req.method);if(!res.ok)throw new Error('Node rejected action ('+res.status+').');if(action==='storage-summary.read'){const p=core.sanitizeStorageSummary(res.payload);if(!p)throw new Error('Invalid storage summary.');out.className='result ok';out.textContent=p.volume+' · '+fmtBytes(p.usedBytes)+' used of '+fmtBytes(p.totalBytes)+' · '+fmtBytes(p.freeBytes)+' free · '+p.usedPercent+'% used.';return}if(action==='rustdesk.launch'){const p=core.sanitizeLaunchResult(res.payload);if(!p)throw new Error('Invalid RustDesk launch response.');out.className='result ok';out.textContent='RustDesk launched on '+d.label+'. No path or arguments were sent.';return}throw new Error('No local renderer for action.')}catch(e){out.className='result bad';out.textContent=e.name==='AbortError'?'Action timed out.':e.message}finally{document.getElementById('actionToken').value=''}}`;
const newRun=`async function freshActionChallenge(d,action,token){const pre=core.actionChallengeRequest(d,action);if(!pre)return'';const res=await authRequest(pre.url,token,pre.method);if(!res.ok)throw new Error('Fresh action catalog rejected ('+res.status+').');const catalog=core.sanitizeActionCatalog(res.payload,d.capabilities),challenge=core.actionChallengeFromCatalog(res.payload,d.capabilities,action);if(!catalog||!catalog.actions.includes(action)||!challenge)throw new Error('Node did not return a valid fresh challenge for this approved action.');return challenge}\nasync function runApprovedAction(){const id=document.getElementById('actionDevice').value,action=document.getElementById('actionId').value,token=document.getElementById('actionToken').value.trim(),out=document.getElementById('actionResult'),d=devices.find(x=>x.id===id);if(!d||!core.canExecuteAction(d,action)||!token){out.className='result bad';out.textContent='Action is not both advertised and locally approved, or token is missing.';return}out.className='result';out.textContent='Refreshing action catalog and acquiring one-time challenge…';try{const challenge=await freshActionChallenge(d,action,token),req=core.actionExecutionRequest(d,action,challenge);if(!req)throw new Error('Action request could not be built from the fresh challenge.');const res=await authRequest(req.url,token,req.method,undefined,req.challenge);if(!res.ok)throw new Error('Node rejected challenged action ('+res.status+').');if(action==='storage-summary.read'){const p=core.sanitizeStorageSummary(res.payload);if(!p)throw new Error('Invalid storage summary.');out.className='result ok';out.textContent=p.volume+' · '+fmtBytes(p.usedBytes)+' used of '+fmtBytes(p.totalBytes)+' · '+fmtBytes(p.freeBytes)+' free · '+p.usedPercent+'% used. One-time challenge consumed.';return}if(action==='rustdesk.launch'){const p=core.sanitizeLaunchResult(res.payload);if(!p)throw new Error('Invalid RustDesk launch response.');out.className='result ok';out.textContent='RustDesk launched on '+d.label+'. One-time challenge consumed; no path or arguments were sent.';return}throw new Error('No local renderer for action.')}catch(e){out.className='result bad';out.textContent=e.name==='AbortError'?'Action timed out.':e.message}finally{document.getElementById('actionToken').value=''}}`;
html=rep(html,oldRun,newRun,'html challenged action runner');
