const newHandoff=`async function runRustDeskHandoff(){const nodeId=document.getElementById('handoffDevice').value,peerId=document.getElementById('handoffPeerId').value.trim(),token=document.getElementById('handoffToken').value.trim(),out=document.getElementById('handoffResult'),d=devices.find(x=>x.id===nodeId);if(!d||!core.canHandoffRustDesk(d)||!core.sanitizePeerId(peerId)||!token){out.className='result bad';out.textContent='Select an approved controller node, enter a valid RustDesk ID and current Node Agent token.';document.getElementById('handoffPeerId').value='';document.getElementById('handoffToken').value='';return}out.className='result';out.textContent='Refreshing action catalog and acquiring one-time rustdesk.connect challenge…';try{const challenge=await freshActionChallenge(d,'rustdesk.connect',token),req=core.rustDeskHandoffRequest(d,peerId,challenge);if(!req)throw new Error('Handoff request could not be built from the fresh challenge.');const res=await authRequest(req.url,token,req.method,req.body,req.challenge);if(!res.ok)throw new Error('Node rejected challenged handoff ('+res.status+').');const p=core.sanitizeHandoffResult(res.payload);if(!p)throw new Error('Invalid RustDesk handoff response.');out.className='result ok';out.textContent='RustDesk handoff started on '+d.label+'. One-time challenge consumed. Connection/authentication remains inside RustDesk; no password was sent.'}catch(e){out.className='result bad';out.textContent=e.name==='AbortError'?'Handoff timed out.':e.message}finally{document.getElementById('handoffPeerId').value='';document.getElementById('handoffToken').value=''}}`;
